[{"order":1,"type":"heading","text":"Using Node.js Tasks with cy.task() for DB and File Operations in Cypress"},{"order":2,"type":"paragraph","text":"Cypress tests run directly inside the browser, which secures the execution environment but limits direct access to the operating system. To perform backend operations like querying a database, reading or writing files outside the project sandbox, or executing system commands, Cypress provides the 'cy.task()' command. This command acts as a bridge, executing code in the Node.js background process and returning the result to your browser-based test."},{"order":3,"type":"subheading","text":"Configuring Tasks in cypress.config.js"},{"order":4,"type":"paragraph","text":"To register tasks, you must define them within the 'setupNodeEvents' function in your Cypress configuration file. Each task is a function that can accept a single argument and must return a value or a promise."},{"order":5,"type":"code","text":"const { defineConfig } = require("cypress");
const fs = require("fs");
const path = require("path");

module.exports = defineConfig({
  e2e: {
    setupNodeEvents(on, config) {
      on("task", {
        // Task 1: Write data to a JSON file
        writeJsonFile({ filename, data }) {
          const filePath = path.resolve(filename);
          fs.writeFileSync(filePath, JSON.stringify(data, null, 2));
          return null; // Tasks must return a value or null
        },
        // Task 2: Mock database query
        queryDatabase(query) {
          // In a real application, connect to your DB (pg, mysql, mongodb, etc.)
          console.log("Executing query:", query);
          return [
            { id: 1, username: "test_user", email: "test@example.com" }
          ];
        }
      });
    },
  },
});"},{"order":6,"type":"subheading","text":"Executing File Operations in Tests"},{"order":7,"type":"paragraph","text":"Once configured, you can call the task using 'cy.task()' inside your test files. Here is an example of writing test data to a local JSON file during a test run."},{"order":8,"type":"code","text":"describe("File Operations via cy.task()", () => {
  it("should write test results to a local JSON file", () => {
    const testData = { status: "passed", timestamp: Date.now() };

    cy.task("writeJsonFile", {
      filename: "cypress/fixtures/test-output.json",
      data: testData
    }).then(() => {
      // Verify the file was written successfully
      cy.readFile("cypress/fixtures/test-output.json").should("deep.equal", testData);
    });
  });
});"},{"order":9,"type":"subheading","text":"Executing Database Operations in Tests"},{"order":10,"type":"paragraph","text":"Database tasks are highly useful for seeding test data before a test runs, or verifying that an action in the UI correctly updated the database state."},{"order":11,"type":"code","text":"describe("Database Operations via cy.task()", () => {
  it("should query the database and verify user records", () => {
    const sqlQuery = "SELECT * FROM users WHERE id = 1";

    cy.task("queryDatabase", sqlQuery).then((users) => {
      expect(users).to.have.lengthOf(1);
      expect(users[0].username).to.equal("test_user");
    });
  });
});"},{"order":12,"type":"subheading","text":"Best Practices for Using cy.task()"},{"order":13,"type":"bullet_point","text":"Always return a value: Cypress tasks will fail with a timeout error if they do not return a value, a Promise, or 'null'."},{"order":14,"type":"bullet_point","text":"Limit argument passing: 'cy.task()' only accepts a single argument. If you need to pass multiple parameters, wrap them in an object."},{"order":15,"type":"bullet_point","text":"Keep tasks lightweight: Avoid running long-blocking synchronous operations in Node.js, as they can slow down your test execution suite."},{"order":16,"type":"bullet_point","text":"Secure credentials: Do not hardcode database passwords in your configuration. Use Node environment variables ('process.env') to manage sensitive connection strings."}]
